import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Design palette
  const colors = {
    surface: new THREE.Color('#14141a'),
    accent: new THREE.Color('#ff2a38'),
    paper: new THREE.Color('#e8ecf2')
  };

  // Grid dimensions
  const gridWidth = 5.5;
  const gridHeight = 3.5;
  const gutter = 0.25;
  const cellDepth = 0.06;
  const padding = 0.5;

  const gridLeft = -gridWidth / 2;
  const gridTop = gridHeight / 2;

  // Cell definitions with all text and sizing
  const cells = [
    {
      idx: 0,
      name: 'dominant',
      pos: [gridLeft + 3.25 / 2, 0, 0],
      size: [3.25, 3.5],
      value: '0.002 mm',
      valueFontSize: 124,
      valueLetterSpacing: -0.01,
      label: 'Case tolerance, CNC pass',
      labelFontSize: 18,
      labelLetterSpacing: 0.08
    },
    {
      idx: 1,
      name: 'topRight',
      pos: [gridLeft + 3.25 + gutter + 2.0 / 2, gridTop - 1.625 / 2, 0],
      size: [2.0, 1.625],
      value: '38 h',
      valueFontSize: 68,
      valueLetterSpacing: -0.005,
      label: 'Power reserve, NA-01',
      labelFontSize: 18,
      labelLetterSpacing: 0.08
    },
    {
      idx: 2,
      name: 'bottomRight',
      pos: [gridLeft + 3.25 + gutter + 2.0 / 2, -gridTop + 1.625 / 2, 0],
      size: [2.0, 1.625],
      value: '214',
      valueFontSize: 68,
      valueLetterSpacing: -0.005,
      label: 'Components per calibre',
      labelFontSize: 18,
      labelLetterSpacing: 0.08
    }
  ];

  const meshes = [];

  // Create cell slabs
  cells.forEach((cellDef) => {
    const geometry = new THREE.BoxGeometry(cellDef.size[0], cellDef.size[1], cellDepth);

    const material = new THREE.MeshStandardMaterial({
      color: colors.surface,
      metalness: 0.45,
      roughness: 0.5,
      clearcoat: 0.2
    });

    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.set(cellDef.pos[0], cellDef.pos[1], cellDef.pos[2]);
    mesh.userData.cellIdx = cellDef.idx;
    group.add(mesh);
    meshes.push(mesh);

    // Accent tick bar (red, emissive)
    const tickGeometry = new THREE.BoxGeometry(0.4, 0.05, cellDepth + 0.02);
    const tickMaterial = new THREE.MeshStandardMaterial({
      color: colors.accent,
      emissive: colors.accent,
      emissiveIntensity: 1.3,
      metalness: 0.3,
      roughness: 0.4,
      clearcoat: 0.15
    });

    const tickMesh = new THREE.Mesh(tickGeometry, tickMaterial);
    const tickX = cellDef.pos[0] - cellDef.size[0] / 2 + padding + 0.2;
    const tickY = cellDef.pos[1] + cellDef.size[1] / 2 - padding + 0.025;
    tickMesh.position.set(tickX, tickY, cellDef.pos[2] + 0.035);
    group.add(tickMesh);
    meshes.push(tickMesh);
  });

  // Header caption
  try {
    const headerMesh = ctx.fontAtlas.createMesh('ATELIER METRICS / Q2 2026', {
      font: 'JetBrains Mono',
      fontSize: 18,
      fontWeight: 700,
      letterSpacing: 0.12,
      color: colors.paper
    });
    if (headerMesh) {
      headerMesh.position.set(gridLeft + padding, gridTop + padding, 0.1);
      group.add(headerMesh);
      meshes.push(headerMesh);
    }
  } catch (err) {
    console.warn('Header caption creation failed', err);
  }

  // Cell text (values and labels)
  cells.forEach((cellDef) => {
    // Value text
    try {
      const valueMesh = ctx.fontAtlas.createMesh(cellDef.value, {
        font: 'Lora',
        fontSize: cellDef.valueFontSize,
        fontWeight: 600,
        letterSpacing: cellDef.valueLetterSpacing,
        color: colors.paper
      });
      if (valueMesh) {
        valueMesh.position.set(cellDef.pos[0], cellDef.pos[1] + 0.5, 0.08);
        group.add(valueMesh);
        meshes.push(valueMesh);
      }
    } catch (err) {
      console.warn(`Value text "${cellDef.value}" creation failed`, err);
    }

    // Label text
    try {
      const labelMesh = ctx.fontAtlas.createMesh(cellDef.label, {
        font: 'JetBrains Mono',
        fontSize: cellDef.labelFontSize,
        fontWeight: 400,
        letterSpacing: cellDef.labelLetterSpacing,
        color: colors.paper
      });
      if (labelMesh) {
        labelMesh.position.set(cellDef.pos[0], cellDef.pos[1] - 0.7, 0.08);
        group.add(labelMesh);
        meshes.push(labelMesh);
      }
    } catch (err) {
      console.warn(`Label text "${cellDef.label}" creation failed`, err);
    }
  });

  // Entrance animation: stagger-cards with fade-up (500ms, 80ms stagger)
  let delayIndex = 0;
  for (let i = 0; i < cells.length; i++) {
    // Each cell contributes 2 mesh pairs (cell slab + tick) + 2 text meshes = 4 total
    // But we want to stagger per cell, not per mesh
    for (let j = 0; j < 4; j++) {
      const meshIndex = i * 4 + j;
      if (meshes[meshIndex]) {
        gsap.from(meshes[meshIndex], {
          opacity: 0,
          y: `+=${0.2}`,
          duration: 0.5,
          delay: i * 0.08,
          ease: 'power2.out'
        });
      }
    }
  }

  // Hover interaction: press-down (scale 0.97, 120ms back.out) → weighted-settle (overshoot, 900ms power4.out)
  let isHovering = false;

  group.userData.handlers = {
    onPointerEnter: () => {
      if (isHovering) return;
      isHovering = true;

      gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out'
      });
    },

    onPointerLeave: () => {
      isHovering = false;

      gsap.to(group.scale, {
        x: 1.0,
        y: 1.0,
        z: 1.0,
        duration: 0.9,
        ease: 'power4.out'
      });
    }
  };

  // Cleanup
  group.userData.cleanup = () => {
    gsap.killTweensOf(group);
    gsap.killTweensOf(group.scale);

    meshes.forEach((mesh) => {
      gsap.killTweensOf(mesh);
      if (mesh.geometry) mesh.geometry.dispose();
      if (mesh.material) {
        if (Array.isArray(mesh.material)) {
          mesh.material.forEach((m) => m.dispose());
        } else {
          mesh.material.dispose();
        }
      }
    });
  };

  return group;
}
